import{_ as o,a0 as p,w as r,s as g,ao as l,I as e,a1 as t,A as i,x as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何修改 Linux 的 GRUB 启动背景 | LCTT x X-CMD","titleTemplate":false,"description":"如何修改 Linux 的 GRUB 启动背景 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何修改 Linux 的 GRUB 启动背景 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何修改 Linux 的 GRUB 启动背景 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170215 How to change the Linux Boot Splash screen","title":"如何修改 Linux 的 GRUB 启动背景","tag":"201703","desc":""},"relativePath":"201703/20170215 How to change the Linux Boot Splash screen.md","filePath":"[post].md"}'),h={name:"201703/20170215 How to change the Linux Boot Splash screen.md"};function d(u,s,m,c,b,k){const a=p("Link");return r(),g("div",null,[s[20]||(s[20]=l('<h1 id="如何修改-linux-的-grub-启动背景" tabindex="-1">如何修改 Linux 的 GRUB 启动背景 <a class="header-anchor" href="#如何修改-linux-的-grub-启动背景" aria-label="Permalink to “如何修改 Linux 的 GRUB 启动背景”">​</a></h1><p><strong>何为 GRUB 背景（ Splash ）？</strong></p><p>GRUB 背景（ Splash ）只不过是一张图像，在 Linux 系统启动的时候显示为背景。你可能知道 Grub (<strong>GR</strong>and <strong>U</strong>nified <strong>B</strong>ootloader 的简写) 是主流 Linux 发行版中广泛使用的启动装载程序 (bootloader)。以 RedHat 为例，你会发现它在系统启动之时显示为空白或者是一个黑色背景。</p><p>GRUB 背景（ Splash ）的相关定义在 <code>grub.conf</code> 文件中，并且 splash 背景图像应该存储在 <code>/boot</code> 分区中。如果你觉得默认的空白屏相当无趣，同时又想按照自己的意愿来修改它，那么赶紧阅读下方的每个步骤吧。</p><h3 id="开始前需要哪些准备工作" tabindex="-1">开始前需要哪些准备工作 <a class="header-anchor" href="#开始前需要哪些准备工作" aria-label="Permalink to “开始前需要哪些准备工作”">​</a></h3><ol><li>ImageMagick (仅在命令行中使用) 或者 GIMP (GUI 中使用)</li><li>一个样例图像</li></ol><h3 id="使用-gui-修改-grub-的-splash-背景" tabindex="-1">使用 GUI 修改 Grub 的 Splash 背景 <a class="header-anchor" href="#使用-gui-修改-grub-的-splash-背景" aria-label="Permalink to “使用 GUI 修改 Grub 的 Splash 背景”">​</a></h3><p>首先然我们来使用 GUI 来进行操作吧，这里我们使用 GIMP 来作为图像编辑器。</p><p><strong>步骤 1</strong>、 使用 GIMP 打开图像 (路径为：<em>应用 (Applications)</em> --&gt; <em>图像 (Graphics)</em> --&gt; <em>GIMP 程序 (GNU Image Manipulation Program)</em>)</p><p><strong>步骤 2</strong>、 现在我们需要按实际情况将图像缩放到 640x480 大小。为此，需要点击 <em>图像 (Image)</em> --&gt; <em>缩放图像 (Scale Image)</em>。记住，要如下图参数进行设置。修改宽度为 640，高度为 480。其他保持不变。</p>',10)),e("p",null,[t(a,{href:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/big/scale.JPG"},{default:i(()=>[...s[0]||(s[0]=[e("img",{src:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/scale.JPG",alt:"缩放 image"},null,-1)])]),_:1})]),s[21]||(s[21]=e("p",null,[n("点击 "),e("strong",null,"缩放 (Scale)"),n(" 按钮")],-1)),s[22]||(s[22]=e("p",null,[e("strong",null,"步骤 3"),n("、 然后，我们需要索引图像，让它仅使用 14 色。为此，点击 "),e("em",null,"图像 (Image)"),n(' --> 模式 (Mode) --> 索引 (Indexed)。点选 "生成最优调色板 (generate optimum palette)" 选项，并设置颜色最大值 (maximum number of colors) 为 14 (如下)。')],-1)),e("p",null,[t(a,{href:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/big/index.JPG"},{default:i(()=>[...s[1]||(s[1]=[e("img",{src:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/index.JPG",alt:"最优调色板限制为 14 色"},null,-1)])]),_:1})]),s[23]||(s[23]=e("p",null,[n("点击 "),e("em",null,"转换 (convert)"),n(" 按钮")],-1)),s[24]||(s[24]=e("p",null,[e("strong",null,"步骤 4"),n('、 保存文件。这里以文件名为 "UxTechno.xpm" 来保存。')],-1)),e("p",null,[t(a,{href:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/big/save.JPG"},{default:i(()=>[...s[2]||(s[2]=[e("img",{src:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/save.JPG",alt:"保存图像文件"},null,-1)])]),_:1})]),s[25]||(s[25]=e("p",null,[e("strong",null,"步骤 5"),n('、 以 Zip 方式压缩文件。为此，转到文件的保存位置 --> 右击并选择 "压缩 (Compress)" 选项，选择 "gzip" 方法来压缩。')],-1)),e("p",null,[t(a,{href:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/big/compress.JPG"},{default:i(()=>[...s[3]||(s[3]=[e("img",{src:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/compress.JPG",alt:""},null,-1)])]),_:1})]),s[26]||(s[26]=l(`<p><strong>步骤 6</strong>、 现在复制或移动 &quot;UxTechno.xpm.gz&quot; 到 <code>/boot/grub/UxTechno.xpm.gz</code>。</p><p><strong>步骤 7</strong>、 这一步，打开 <code>/boot/grub/grub.conf</code> 文件编辑 <code>splashimage</code> 参数如下，并保存文件。</p><p>最后，文件的内容应该是像这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grub.conf</span></span>
<span class="line"><span>generated by anaconda</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Note that you do not have to rerun grub after making changes to this file</span></span>
<span class="line"><span># NOTICE: You have a /boot partition. This means</span></span>
<span class="line"><span>    that # all kernel and initrd paths are relative to /boot/, eg. # root</span></span>
<span class="line"><span>    (hd0,0) # kernel /vmlinuz-version ro root=/dev/sda2 # initrd</span></span>
<span class="line"><span>    /initrd-[generic-]version.img #boot=/dev/sda default=0 timeout=5</span></span>
<span class="line"><span>    splashimage=(hd0,0)/grub/UxTechno.xpm.gz</span></span>
<span class="line"><span>    hiddenmenu   </span></span>
<span class="line"><span>    title Red Hat Enterprise Linux (2.6.32-220.el6.x86_64)</span></span>
<span class="line"><span>    root (hd0,0)</span></span>
<span class="line"><span>    kernel /vmlinuz-2.6.32-220.el6.x86_64 ro root=UUID=1d8c5075-1a5b-4fdc-ba15-0458b65c6012 rd_NO_LUKS rd_NO_LVM LANG=en_US.UTF-8 rd_NO_MD quiet SYSFONT=latarcyrheb-sun16 rhgb</span></span>
<span class="line"><span>    crashkernel=auto KEYBOARDTYPE=pc KEYTABLE=us rd_NO_DM initrd</span></span>
<span class="line"><span>    /initramfs-2.6.32-220.el6.x86_64.img</span></span></code></pre></div><p>当你重启服务器之后，你讲看到如下效果的 splash 背景图像：</p>`,5)),e("p",null,[t(a,{href:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/big/Uxtecho_splash.JPG"},{default:i(()=>[...s[4]||(s[4]=[e("img",{src:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/Uxtecho_splash.JPG",alt:""},null,-1)])]),_:1})]),s[27]||(s[27]=l(`<h3 id="使用命令行修改-grub-的-splash-背景" tabindex="-1">使用命令行修改 Grub 的 Splash 背景 <a class="header-anchor" href="#使用命令行修改-grub-的-splash-背景" aria-label="Permalink to “使用命令行修改 Grub 的 Splash 背景”">​</a></h3><p>如果说你是命令行的超级粉丝，那就使用如下方法吧。</p><p><strong>步骤 1</strong>、 开始之前，我们需要修改图像的像素分辨率。为此，我们还需要在 Linux 系统上安装好 ImageMagick。在 CentOS / RHEL 上使用如下命令来进行交叉检查。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># rpm -qa|grep -i ImageMagick</span></span></code></pre></div><p>如果命令没有返回输出 (即空白)，这意味这你的系统上还没有安装 ImageMagick。你必须运行下面的命令来安装它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install ImageMagick</span></span></code></pre></div><p>安装好了重新复核一下，你会得到类似如下的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># rpm -qa|grep -i ImageMagick</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ImageMagick-6.5.4.7-5.el6.x86_64</span></span></code></pre></div><p>然后，继续接下来的配置。这里我使用 UxTechno 的 logo 来做 splash 背景图像。</p><p><strong>步骤 2</strong>、 使用如下命令来转换像素深度。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># convert -depth 8 -colors 14 -resize 640x480 uxtechno_logo.jpg uxtechno_logo.xpm</span></span></code></pre></div><p>上述选项的意义如下：</p><ol><li>最大使用 14 色</li><li>分辨率为 640x480</li><li>使用 xpm 格式</li></ol><p><strong>步骤 3</strong>、 以 Zip 压缩文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># gzip uxtechno_logo.xpm</span></span></code></pre></div><p><strong>步骤 4</strong>、 复制文件到 <code>/boot</code> 分区。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cp uxtechno_logo.xpm.gz /boot/grub/</span></span></code></pre></div><p><strong>步骤 5</strong>、 在 <code>/boot/grub/grub.conf</code> 文件中修改 <code>splashimage</code> 参数如下，并保存文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>splashimage=(hd0,0)/grub/uxtechno_logo.xpm</span></span></code></pre></div><p><strong>步骤 6</strong>、 最后，使用 <code>reboot</code> 命令重启服务器。启动界面将显示使用 GUI 方式第 7 步中的图像。</p><hr><p>译者简介：</p>`,22)),e("p",null,[t(a,{href:"http://GHLandy.com"},{default:i(()=>[...s[5]||(s[5]=[n("GHLandy",-1)])]),_:1}),s[6]||(s[6]=n(" —— 生活中所有欢乐与苦闷都应藏在心中，有些事儿注定无人知晓，自己也无从说起。",-1))]),s[28]||(s[28]=e("hr",null,null,-1)),e("p",null,[s[8]||(s[8]=n("via: ",-1)),t(a,{href:"https://www.howtoforge.com/tutorial/how-to-change-the-linux-splash-screen/"},{default:i(()=>[...s[7]||(s[7]=[n("https://www.howtoforge.com/tutorial/how-to-change-the-linux-splash-screen/",-1)])]),_:1})]),e("p",null,[s[12]||(s[12]=n("作者：",-1)),t(a,{href:"https://www.howtoforge.com/tutorial/how-to-change-the-linux-splash-screen/"},{default:i(()=>[...s[9]||(s[9]=[n("MANMOHAN MIRKAR",-1)])]),_:1}),s[13]||(s[13]=n(" 译者：",-1)),t(a,{href:"https://github.com/GHLandy"},{default:i(()=>[...s[10]||(s[10]=[n("GHLandy",-1)])]),_:1}),s[14]||(s[14]=n(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[11]||(s[11]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[17]||(s[17]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:i(()=>[...s[16]||(s[16]=[n("Linux中国",-1)])]),_:1}),s[19]||(s[19]=n(" 荣誉推出",-1))])])}const w=o(h,[["render",d]]);export{f as __pageData,w as default};
